function APR:GetTextColor(scope, role, trackerStyle)
    if self.GetThemeStatusColor then
        local status = self:GetThemeStatusColor(role)
        if status then return status end
    end
    local custom = self:GetCustomTextColor(scope, role)
    if custom then return custom end
    -- Guide instructions can carry either a title role or legacy yellow markup.
    -- Under integrated skins both follow the provider's live accent.
    if scope == "currentStep" and (role == "title" or role == "warning") then
        local provider = self.GetAppearanceProvider and self:GetAppearanceProvider(scope)
        if provider == "EllesmereUI" or provider == "ElvUI" then
            role = "accent"
            local accent = self:GetCustomTextColor(scope, role)
            if accent then return accent end
        end
    end
    local themedRole = role == "activeStep" and "warning" or role or "base"
    if trackerStyle == nil then trackerStyle = self.QuestTracker and self.QuestTracker:Style(scope) end
    if trackerStyle then
        local color = trackerStyle.textColors and trackerStyle.textColors[themedRole]
        if themedRole == "accent" then color = trackerStyle.accent or color end
        if color then return color end
    end
    if self.EllesmereUISkin then
        local themed = self.EllesmereUISkin:GetTextColor(themedRole, scope)
        if themed then return themed end
    end
    if self.GetNativeThemeTextColor then
        local themed = self:GetNativeThemeTextColor(role, scope)
        if themed then return themed end
    end
    local scoped, general = GetAppearance(scope)
    local key = ROLE_KEYS[role or "base"] or "color"

    if scope ~= "general" and scoped[key] then
        return scoped[key]
    end
    return general[key] or DEFAULT_COLORS[key] or DEFAULT_COLORS.color
end--[[APR_DIAG]]; APR.GetTextColor = APRTrace("APR-Core/ui/foundations/TextStyles.lua:194:APR:GetTextColor#11", APR.GetTextColor)--[[/APR_DIAG]]

function APR:GetTextColorHex(scope, role)
    local color = self:GetTextColor(scope, role)
    local r = math.floor(math.max(0, math.min(1, color[1] or 1)) * 255 + 0.5)
    local g = math.floor(math.max(0, math.min(1, color[2] or 1)) * 255 + 0.5)
    local b = math.floor(math.max(0, math.min(1, color[3] or 1)) * 255 + 0.5)
    return string.format("%02x%02x%02x", r, g, b)
end--[[APR_DIAG]]; APR.GetTextColorHex = APRTrace("APR-Core/ui/foundations/TextStyles.lua:235:APR:GetTextColorHex#12", APR.GetTextColorHex)--[[/APR_DIAG]]

